package com.mirigangneung.infrastructure.kakao; import com.fasterxml.jackson.databind.*;import com.mirigangneung.common.error.ApiException;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.*;
@Component public class HttpKakaoRouteClient implements KakaoRouteClient {private final KakaoRouteProperties p;private final RestClient c;public HttpKakaoRouteClient(KakaoRouteProperties x){p=x;c=RestClient.builder().baseUrl(x.baseUrl()).build();}public RouteResult walking(double ol,double oo,double dl,double d){if(p.key()==null||p.key().isBlank())return new RouteResult(0,0,List.of());try{String body=c.get().uri(u->u.path("/v1/directions").queryParam("origin",oo+","+ol).queryParam("destination",d+","+dl).build()).header("Authorization","KakaoAK "+p.key()).retrieve().body(String.class);JsonNode n=new ObjectMapper().readTree(body).at("/routes/0");return new RouteResult(n.path("summary").path("distance").asInt(),n.path("summary").path("duration").asInt(),List.of());}catch(Exception e){throw new ApiException("KAKAO_API_ERROR",HttpStatus.BAD_GATEWAY,"Kakao 경로 API를 사용할 수 없습니다.");}}}
